WITH filtered_dates AS MATERIALIZED (SELECT d_date_sk FROM date_dim WHERE d_year = 2002 AND d_moy BETWEEN 4 AND 4+3), filtered_items AS MATERIALIZED (SELECT i_item_sk FROM item WHERE i_category IN ('Books', 'Electronics', 'Sports') AND i_manager_id BETWEEN 91 AND 100), eligible_customers AS MATERIALIZED (SELECT c.c_customer_sk, cd.cd_gender, cd.cd_marital_status, cd.cd_education_status, cd.cd_purchase_estimate, cd.cd_credit_rating, cd.cd_dep_count, cd.cd_dep_employed_count, cd.cd_dep_college_count FROM customer c JOIN customer_address ca ON c.c_current_addr_sk = ca.ca_address_sk JOIN customer_demographics cd ON cd.cd_demo_sk = c.c_current_cdemo_sk WHERE ca.ca_county IN ('Northampton County','Pendleton County','Perry County','Randolph County','Woods County') AND c.c_birth_month IN (7, 11) AND cd.cd_marital_status IN ('S', 'M', 'M') AND cd.cd_education_status IN ('4 yr Degree', 'Unknown', 'Unknown') AND cd.cd_gender = 'F'), store_eligible AS MATERIALIZED (SELECT e.* FROM eligible_customers e WHERE EXISTS (SELECT 1 FROM store_sales ss JOIN filtered_dates d ON ss.ss_sold_date_sk = d.d_date_sk JOIN filtered_items i ON ss.ss_item_sk = i.i_item_sk WHERE ss.ss_customer_sk = e.c_customer_sk AND ss.ss_sales_price / ss.ss_list_price BETWEEN 77 * 0.01 AND 87 * 0.01)), remote_customers AS (SELECT ws.ws_bill_customer_sk AS customer_sk FROM store_eligible e JOIN web_sales ws ON ws.ws_bill_customer_sk = e.c_customer_sk JOIN filtered_dates d ON ws.ws_sold_date_sk = d.d_date_sk JOIN filtered_items i ON ws.ws_item_sk = i.i_item_sk WHERE ws.ws_sales_price / ws.ws_list_price BETWEEN 77 * 0.01 AND 87 * 0.01 UNION SELECT cs.cs_ship_customer_sk AS customer_sk FROM store_eligible e JOIN catalog_sales cs ON cs.cs_ship_customer_sk = e.c_customer_sk JOIN filtered_dates d ON cs.cs_sold_date_sk = d.d_date_sk JOIN filtered_items i ON cs.cs_item_sk = i.i_item_sk WHERE cs.cs_sales_price / cs.cs_list_price BETWEEN 77 * 0.01 AND 87 * 0.01) SELECT e.cd_gender, e.cd_marital_status, e.cd_education_status, count(*) cnt1, e.cd_purchase_estimate, count(*) cnt2, e.cd_credit_rating, count(*) cnt3, e.cd_dep_count, count(*) cnt4, e.cd_dep_employed_count, count(*) cnt5, e.cd_dep_college_count, count(*) cnt6 FROM store_eligible e JOIN remote_customers r ON r.customer_sk = e.c_customer_sk GROUP BY e.cd_gender, e.cd_marital_status, e.cd_education_status, e.cd_purchase_estimate, e.cd_credit_rating, e.cd_dep_count, e.cd_dep_employed_count, e.cd_dep_college_count ORDER BY e.cd_gender, e.cd_marital_status, e.cd_education_status, e.cd_purchase_estimate, e.cd_credit_rating, e.cd_dep_count, e.cd_dep_employed_count, e.cd_dep_college_count LIMIT 100;
